import{_ as l,o as r,c as t,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"上位毁灭神（小白狼）","description":"","frontmatter":{},"headers":[],"relativePath":"底层/人物/上位毁灭神.md","filePath":"底层/人物/上位毁灭神.md","lastUpdated":1787065118000}'),i={name:"底层/人物/上位毁灭神.md"};function n(s,a,e,g,h,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="上位毁灭神-小白狼" tabindex="-1">上位毁灭神（小白狼） <a class="header-anchor" href="#上位毁灭神-小白狼" aria-label="Permalink to &quot;上位毁灭神（小白狼）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：通常称为&quot;上位毁灭神&quot;或&quot;小白狼&quot;</li><li><strong>身份</strong>：上位毁灭神权的初代载体</li><li><strong>外观</strong>：雌性，毛色为白色，体型娇小</li><li><strong>身世</strong>：原非当前狼族聚落成员，家乡在一次神权失控中被完全抹除</li><li><strong>收养经历</strong>：失魂落魄时被当前狼族聚落的村长捡走收养</li><li><strong>特质</strong>：深知自身神权的极端危险性，性格谨慎而富有责任感</li><li><strong>时代</strong>：黑暗时代中后期</li><li><strong>状态</strong>：已死亡，但意识与神权残余仍存在于原家乡的深坑中</li></ul><h2 id="外貌特征" tabindex="-1">外貌特征 <a class="header-anchor" href="#外貌特征" aria-label="Permalink to &quot;外貌特征&quot;">​</a></h2><h3 id="本体形态" tabindex="-1">本体形态 <a class="header-anchor" href="#本体形态" aria-label="Permalink to &quot;本体形态&quot;">​</a></h3><ul><li><strong>毛色</strong>：纯白色，毛发光洁柔顺</li><li><strong>体型</strong>：相比普通狼族更加娇小</li><li><strong>眼睛</strong>：受神权影响为白瞳，在使用神权时会发光</li><li><strong>特殊标记</strong>：身上可能带有毁灭神权的微弱印记，但外表难以察觉</li></ul><h3 id="神环形态" tabindex="-1">神环形态 <a class="header-anchor" href="#神环形态" aria-label="Permalink to &quot;神环形态&quot;">​</a></h3><ul><li><strong>形态描述</strong>：一个纯白色的巨大发光圆环</li><li><strong>象征意义</strong>：象征删除，句号，结束，关闭</li><li><strong>嵌套关系</strong>：可以套住创造与变化的神环，体现着其足以删除一切的权柄</li></ul><h2 id="毁灭神权特质" tabindex="-1">毁灭神权特质 <a class="header-anchor" href="#毁灭神权特质" aria-label="Permalink to &quot;毁灭神权特质&quot;">​</a></h2><h3 id="神权本质" tabindex="-1">神权本质 <a class="header-anchor" href="#神权本质" aria-label="Permalink to &quot;神权本质&quot;">​</a></h3><p>作为上位毁灭神权的载体，她掌握着毁灭神权的底层版本：</p><ul><li><strong>删除能力</strong>：字面意义上的删除一切，无论是否合理，极端危险，能够删除任何存在，包括物质、能量、概念</li><li><strong>悖论特性</strong>：神权本身存在逻辑悖论，无法完全删除自身</li></ul><h3 id="自我认知与限制" tabindex="-1">自我认知与限制 <a class="header-anchor" href="#自我认知与限制" aria-label="Permalink to &quot;自我认知与限制&quot;">​</a></h3><p>上位毁灭神对自身神权有着清醒的认知，这种认知源于亲身经历的巨大悲剧：</p><ol><li><strong>危险性认知</strong>：因亲自体验过神权失控的毁灭性后果（家乡被完全抹除），她比任何人都更了解其破坏力</li><li><strong>自我限制</strong>：基于对悲剧的恐惧和对他人安全的责任感，主动限制神权的使用</li><li><strong>道德约束</strong>：怀有强烈的道德感和内疚感，不愿再让任何人经历她所造成的那种悲剧</li></ol><h2 id="重要经历" tabindex="-1">重要经历 <a class="header-anchor" href="#重要经历" aria-label="Permalink to &quot;重要经历&quot;">​</a></h2><h3 id="神权失控与家乡抹除" tabindex="-1">神权失控与家乡抹除 <a class="header-anchor" href="#神权失控与家乡抹除" aria-label="Permalink to &quot;神权失控与家乡抹除&quot;">​</a></h3><p><strong>事件概述</strong>：在一次使用神权时，小白狼因未能成功控制毁灭力量而<strong>彻底抹除了自己的家乡</strong>。</p><ul><li><strong>失控过程</strong>：神权力量意外爆发，超出可控范围</li><li><strong>抹除结果</strong>：整个村子完全消失，原地只剩下一个<strong>巨大的圆形的坑</strong></li><li><strong>地形特征</strong>：坑洞边缘光滑，深不见底，是毁灭神权完全作用的产物</li><li><strong>心理影响</strong>：这一事件成为小白狼<strong>最底层的心理创伤</strong>，深刻地影响了她的性格和行为</li></ul><p><strong>后续经历</strong>：</p><ol><li><strong>失魂落魄</strong>：事件后小白狼在荒地上失魂落魄地游荡</li><li><strong>被捡收养</strong>：被当前狼族聚落的村长发现并捡走收养</li><li><strong>融入新家</strong>：成为该狼族聚落的一员，并在后来与同为孤儿的**下位毁灭神（主角）**相遇</li><li><strong>共通背景</strong>：两人都是孤儿，都被村长收养，这成为他们建立深厚情感的基础</li></ol><h3 id="早期活动" tabindex="-1">早期活动 <a class="header-anchor" href="#早期活动" aria-label="Permalink to &quot;早期活动&quot;">​</a></h3><ul><li><strong>限制神权</strong>：经历家乡抹除事件后，小白狼走向限制，禁用神权的极端</li><li><strong>自我毁灭尝试</strong>：因深感神权危险性和内心创伤，曾回到原家乡的深坑旁尝试自我毁灭以彻底删除神权</li><li><strong>悖论失败</strong>：因神权逻辑悖论（无法彻底删除自身）而未能完全成功，其只需小白狼主动停止自删除过程，就会完全回归。自删除尝试的地点为原家乡的深坑旁，象征着她试图在悲剧起点终结一切。</li></ul><h3 id="与下位毁灭神的关系" tabindex="-1">与下位毁灭神的关系 <a class="header-anchor" href="#与下位毁灭神的关系" aria-label="Permalink to &quot;与下位毁灭神的关系&quot;">​</a></h3><ul><li><strong>青梅竹马</strong>：与下位毁灭神（主角，灰色狼）从小相识，关系亲密</li><li><strong>互相认知</strong>：双方都知道对方的身份和神权特质</li><li><strong>劝诫与引导</strong>：曾试图劝主角限制自身的神权，教导其谨慎使用力量</li><li><strong>共同经历</strong>：一同度过多年时光，建立了深厚的情感联系</li></ul><h3 id="死亡事件" tabindex="-1">死亡事件 <a class="header-anchor" href="#死亡事件" aria-label="Permalink to &quot;死亡事件&quot;">​</a></h3><ul><li><strong>时间</strong>：奴隶队袭击村庄时期</li><li><strong>死因</strong>：被一支<strong>普通的铁矛</strong>刺死</li><li><strong>武器特性</strong>：这支铁矛本身并无特殊之处，只是普通的武器</li><li><strong>摒弃神权</strong>：掌握毁灭神权的存在，即使是面对死亡也不愿动用自己的神权，最终死于最普通的武器</li><li><strong>死亡影响</strong>：她的死亡成为引爆主角仇恨、促使主角登神的<strong>导火索之一</strong></li></ul><h3 id="死后影响" tabindex="-1">死后影响 <a class="header-anchor" href="#死后影响" aria-label="Permalink to &quot;死后影响&quot;">​</a></h3><ul><li><strong>武器转化</strong>：刺死她的铁矛后被主角持有，在无尽的杀戮中侵染了毁灭神力，成为标志性武器</li><li><strong>情感驱动</strong>：她的死亡为主角的角色弧光增添了悲情的言情色彩</li><li><strong>残余状态</strong>：小白狼的意识与神权残余皆存在于原家乡的深坑中。这个巨大圆形的坑洞既是悲剧的印记，也是她存在的最后痕迹。</li><li><strong>深层联系</strong>：深坑不仅保留了毁灭神权的残留力量，也封印着小白狼未完全消散的意识，形成了一个特殊的空间节点。</li></ul><h2 id="深层设定-中层真相" tabindex="-1">深层设定（中层真相） <a class="header-anchor" href="#深层设定-中层真相" aria-label="Permalink to &quot;深层设定（中层真相）&quot;">​</a></h2><blockquote><p><strong>中层真相</strong>：以下内容为表层生灵无法知晓的真相。</p></blockquote><h3 id="与狼族的深层关联" tabindex="-1">与狼族的深层关联 <a class="header-anchor" href="#与狼族的深层关联" aria-label="Permalink to &quot;与狼族的深层关联&quot;">​</a></h3><ul><li>上位毁灭的残留/本源出现在狼族地盘<strong>并非偶然</strong>，与<strong>狼族的基因锁、主角作为下位毁灭神载体</strong>等设定存在深层联系</li><li>其&quot;根&quot;很可能埋藏在狼族起源或核心区域，是神机布局的一环</li></ul><h3 id="毁灭神权谱系" tabindex="-1">毁灭神权谱系 <a class="header-anchor" href="#毁灭神权谱系" aria-label="Permalink to &quot;毁灭神权谱系&quot;">​</a></h3><ul><li><strong>上位</strong>：初代载体小白狼 → 死后神权残余+意识存于家乡深坑（本源，特殊空间节点）→ 正传中以<strong>龙鹿寻得继承</strong>为关键线</li><li><strong>下位</strong>：狼族少年（初代下位毁灭神）→ 太空克隆仓库稀释 → 神权回流伏笔</li><li><strong>分支</strong>：小狼史诗为毁灭神权分支继承（构思中）；三条线交叉于狼族起源区域，是神机布局的一环</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a>、<a href="./../../中层/人物/龙鹿" class="layer-link" data-layer="中层">龙鹿</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../表层/人物/小白狼" class="layer-link" data-layer="表层">小白狼（表层档案）</a></p></li><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./../规则/神权体系">神权体系</a></p></li><li><p><a href="./../../中层/人物/狼族少年" class="layer-link" data-layer="中层">狼族少年</a></p></li><li><p><a href="./../../中层/人物/龙鹿" class="layer-link" data-layer="中层">龙鹿</a></p></li><li><p><a href="./../../中层/人物/神机" class="layer-link" data-layer="中层">神机</a></p></li><li><p><a href="./../../中层/世界/历代三神" class="layer-link" data-layer="中层">历代三神</a></p></li></ul><hr>',40)])])}const q=l(i,[["render",n]]);export{c as __pageData,q as default};
